<template>
  <div class="wrapper">
    <div class="product-container">
      <products-component
      v-for="product in returnArray" :key="product.id"
      :productItem="product" :price = 'returnPrice(product)'
      @buy = "addToCart"
     />
    </div>
    <div v-if="isCart" class="cart">
      <cart-component :itemArray="cart" @inc="onInc" @dec="onDec"/>
    </div>
    <div v-else class="empty-cart">
      <div class="image-h">
        <img src="@/assets/cart.png" alt="Cart">
      </div>
    </div>
      
  </div>
 

</template>

<script>
import ProductsComponent from './ProductsComponent'
import CartComponent from './CartComponent'
import { productArray } from '@/constants/index.js' 

export default {
  name: 'MainComponent',
  emits: ['inc', 'dec'],
  components: {
    ProductsComponent,
    CartComponent
  },
  data() {
    return {
      isCart: false,
      productAmount: null,
      cart:  []
    }
  },
  computed: {
    returnArray() {
      return productArray;
    },
  },
  methods: {
    returnPrice(product) {
     let price
     price = product.oldPrice - product.newPrice
     return price
    },
    getString(str_item) {
      let cartTitleArray = str_item.split(" ", 4)
      cartTitleArray.push('...')
      const cartTitle =  cartTitleArray.join(' ')
      return cartTitle
    },
    addToCart(item) {
      let isInCart
      this.isCart = true
      const newTitle = this.getString(item.title)
      let cartItem = {
        id: item.id,
        src: item.src,
        title: newTitle,
        price: item.newPrice,
        count: 1
      }
      isInCart = this.cart.some((element)=>{
        if (element.id === cartItem.id) {
          return true
        } else {
          return false
        }

      })
      if (isInCart === false) {
        this.cart.push(cartItem)
      } else {
        let incCount = this.cart.find((el)=>el.id === item.id)
        incCount.count++
      }
    },

    onInc(ind) {
      this.cart[ind].count++
    },
    onDec(ind) {
       this.cart[ind].count--
       if (this.cart[ind].count < 1) {
        this.cart.splice(ind, 1)
       }
    }
  }

}
</script>

