<template>
    <cart-item
    v-for="(card,ind) in itemArray" :key="card.id"
     :content="card" @inc="onInc(ind)" @dec="onDec(ind)"/>
</template>

<script>
import CartItem from './CardItem.vue'
    export default {
        name: 'CartComponent',
        emits: ['inc', 'dec'],
        components: {
            CartItem
        },
        props: {
            itemArray: {
                type: Array,
                default: () => []
            },
        },
        methods: {
            onInc(ind) {
                this.$emit('inc', ind)
            },
            onDec(ind) {
                this.$emit('dec', ind)
            }
        }
    }
</script>

